import{c as a,Q as l,j as r,m as e}from"./chunks/framework.rWdQudnF.js";const _=JSON.parse('{"title":"架构风格 SOA（面向服务架构)","description":"","frontmatter":{"title":"架构风格 SOA（面向服务架构)"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式/架构风格  总览/架构风格 SOA（面向服务架构).md","filePath":"综合知识/架构设计/架构风格与模式/架构风格  总览/架构风格 SOA（面向服务架构).md","lastUpdated":null}'),i={name:"综合知识/架构设计/架构风格与模式/架构风格  总览/架构风格 SOA（面向服务架构).md"};function o(d,t,n,s,h,b){return l(),r("div",null,[...t[0]||(t[0]=[e('<h2 id="soa-面向服务架构-核心要点" tabindex="-1">SOA（面向服务架构）核心要点 <a class="header-anchor" href="#soa-面向服务架构-核心要点" aria-label="Permalink to &quot;SOA（面向服务架构）核心要点&quot;">​</a></h2><h3 id="一、实施-soa-的关键目标" tabindex="-1">一、实施 SOA 的关键目标 <a class="header-anchor" href="#一、实施-soa-的关键目标" aria-label="Permalink to &quot;一、实施 SOA 的关键目标&quot;">​</a></h3><p>实现企业 IT 资产重用的最大化。</p><h3 id="二、soa-的典型特征" tabindex="-1">二、SOA 的典型特征 <a class="header-anchor" href="#二、soa-的典型特征" aria-label="Permalink to &quot;二、SOA 的典型特征&quot;">​</a></h3><ul><li>可从企业外部访问</li><li>随时可用（服务请求能被及时响应）</li><li>粗粒度接口（粗粒度提供一项特定的业务功能，细粒度服务代表技术构件方法）</li><li>服务分级</li><li>松散耦合（服务提供者和服务使用者分离）</li><li>可重用的服务及服务接口设计管理</li><li>标准化的接口（WSDL、SOAP、XML 是核心）</li><li>支持各种消息模式</li><li>精确定义的服务接口</li></ul><blockquote><p><strong>演进趋势</strong>：从基于对象 → 基于构件 → 基于服务，架构越来越松散耦合，粒度越来越粗，接口越来越标准。</p></blockquote><hr><h2 id="三、关键技术" tabindex="-1">三、关键技术 <a class="header-anchor" href="#三、关键技术" aria-label="Permalink to &quot;三、关键技术&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>协议</th></tr></thead><tbody><tr><td>发现服务</td><td>UDDI、DISCO</td></tr><tr><td>描述服务</td><td>WSDL、XML Schema</td></tr><tr><td>消息格式层</td><td>SOAP、REST</td></tr><tr><td>编码格式层</td><td>XML（DOM、SAX）</td></tr><tr><td>传输协议层</td><td>HTTP、TCP/IP、SMTP 等</td></tr></tbody></table><h3 id="_1-发现服务" tabindex="-1">1. 发现服务 <a class="header-anchor" href="#_1-发现服务" aria-label="Permalink to &quot;1. 发现服务&quot;">​</a></h3><ul><li><strong>UDDI</strong>：用于 Web 服务注册和服务查找，描述服务的概念，定义编程接口，供其他企业调用。</li><li><strong>DISCO</strong>：发现公开服务的功能及交互协议。</li></ul><h3 id="_2-描述服务" tabindex="-1">2. 描述服务 <a class="header-anchor" href="#_2-描述服务" aria-label="Permalink to &quot;2. 描述服务&quot;">​</a></h3><ul><li><strong>WSDL（Web 服务描述语言）</strong>：用于描述 Web 服务的接口和操作功能，描述网络服务。</li></ul><h3 id="_3-消息格式层" tabindex="-1">3. 消息格式层 <a class="header-anchor" href="#_3-消息格式层" aria-label="Permalink to &quot;3. 消息格式层&quot;">​</a></h3><ul><li><strong>SOAP</strong>：为建立 Web 服务和服务请求之间的通信提供支持。</li><li><strong>REST（表述性状态转移）</strong>：只使用 HTTP 和 XML 进行基于 Web 通信的技术，可降低开发复杂性，提高系统可伸缩性。</li></ul><h3 id="_4-编码格式层" tabindex="-1">4. 编码格式层 <a class="header-anchor" href="#_4-编码格式层" aria-label="Permalink to &quot;4. 编码格式层&quot;">​</a></h3><ul><li><strong>XML（可扩展标记语言）</strong>：用于标记电子文件使其具有结构性的标记语言，可标记数据、定义数据类型，是一种允许用户对自己的标记语言进行定义的源语言。</li></ul><hr><h2 id="四、soa-的实现方式" tabindex="-1">四、SOA 的实现方式 <a class="header-anchor" href="#四、soa-的实现方式" aria-label="Permalink to &quot;四、SOA 的实现方式&quot;">​</a></h2><h3 id="_1-web-service" tabindex="-1">1. Web Service <a class="header-anchor" href="#_1-web-service" aria-label="Permalink to &quot;1. Web Service&quot;">​</a></h3><p><strong>三个角色</strong>：</p><ul><li>服务提供者</li><li>服务注册中心（中介，提供交易平台，可有可无）</li><li>服务请求者</li></ul><p><strong>交互流程</strong>：</p><ol><li>服务提供者将服务描述<strong>发布</strong>到服务注册中心。</li><li>服务请求者<strong>查找</strong>服务。</li><li>服务请求者<strong>绑定</strong>查找结果，调用服务。</li></ol><p><strong>六层协议栈</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>作用</th><th>协议示例</th></tr></thead><tbody><tr><td>底层传输层</td><td>负责底层消息的传输</td><td>HTTP、JMS、SMTP</td></tr><tr><td>服务通信协议层</td><td>描述并定义服务间通信的技术标准</td><td>SOAP、REST</td></tr><tr><td>服务描述层</td><td>描述服务的接口和操作功能</td><td>WSDL</td></tr><tr><td>服务层</td><td>对企业应用系统进行包装，通过 WSDL 定义的标准进行调用</td><td>-</td></tr><tr><td>业务流程层</td><td>支持服务发现、服务调用和点到点的服务调用</td><td>WS-BPEL（原文本写WSDpEL）</td></tr><tr><td>服务注册层</td><td>服务的发布与查找</td><td>UDDI</td></tr></tbody></table><h3 id="_2-服务注册表" tabindex="-1">2. 服务注册表 <a class="header-anchor" href="#_2-服务注册表" aria-label="Permalink to &quot;2. 服务注册表&quot;">​</a></h3><ul><li>本质与 Web Service 类似，但使用<strong>注册表</strong>代替服务注册中心。</li><li><strong>服务注册</strong>：应用开发者（服务提供者）在注册表中公布服务功能。</li><li><strong>服务位置</strong>：服务使用者（服务应用开发者）查询注册服务，寻找符合要求的服务。</li><li><strong>服务绑定</strong>：服务使用者利用检索到的服务接口编写代码，与注册的服务绑定、调用、互动。</li></ul><h3 id="_3-企业服务总线-esb" tabindex="-1">3. 企业服务总线（ESB） <a class="header-anchor" href="#_3-企业服务总线-esb" aria-label="Permalink to &quot;3. 企业服务总线（ESB）&quot;">​</a></h3><ul><li><strong>组成</strong>：客户端（服务请求者）、基础架构服务（中间件）、核心集成服务（提供服务）。</li><li><strong>本质</strong>：通过网络实现集成。</li><li><strong>六大功能</strong>： <ol><li>提供位置透明性的消息路由和寻址服务</li><li>支持多种消息传递范型</li><li>支持多种可以广泛使用的传输协议</li><li>支持多种数据格式及其相互转换</li><li>提供日志和监控功能</li></ol></li></ul>',30)])])}const c=a(i,[["render",o]]);export{_ as __pageData,c as default};
